package com.master.bedtime.child;
import android.content.BroadcastReceiver;import android.content.Context;import android.content.Intent;import android.os.Build;
public class MonitorRestartReceiver extends BroadcastReceiver { @Override public void onReceive(Context context,Intent intent){if(!context.getSharedPreferences("cfg",Context.MODE_PRIVATE).getBoolean("setup_complete",false))return;try{Intent service=new Intent(context,BedtimeMonitorService.class);if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.O)context.startForegroundService(service);else context.startService(service);}catch(Exception ignored){}} }
